pragma solidity ^0.8.20;

interface IExternalContract {
    function getUserLpBalance(address token, address user) external view returns (uint256);
    function getAllPendingReward(address user) external view returns (uint256);
}

contract Adapter {
    IExternalContract private constant EXTERNAL = IExternalContract(0xaed7384f03844af886b830862ff0a7afce0a632c);
