// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract Crowdsale {
    address private _owner;
    address private _token;
    address private _wallet;
    uint256 private _rate;
    uint256 private _weiRaised;

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event TokenPurchase(address indexed purchaser, address indexed beneficiary, uint256 value, uint256 amount);

    constructor(address token_, address wallet_, uint256 rate_) {
        _owner = msg.sender;
        _token = token_;
        _wallet = wallet_;
        _rate = rate_;
    }

    modifier onlyOwner() {
        require(msg.sender == _owner);
        _;
    }

    function owner() public view returns (address) {
        return _owner;
    }

    function token() public view returns (address) {
        return _token;
    }

    function wallet() public view returns (address) {
        return _wallet;
    }

    function rate() public view returns (uint256) {
        return _rate;
    }

    function weiRaised() public view returns (uint256) {
        return _weiRaised;
    }

    function setRate(uint256 newRate) public onlyOwner {
        require(newRate > 0);
        _rate = newRate;
    }

    function buyTokens(address beneficiary) public payable {
        require(beneficiary != address(0));
        require(msg.value > 0);

        uint256 weiAmount = msg.value;
        _weiRaised += weiAmount;

        uint256 tokenAmount = weiAmount * _rate;

        IERC20(_token).transfer(beneficiary, tokenAmount);

        emit TokenPurchase(msg.sender, beneficiary, weiAmount, tokenAmount);

        payable(_wallet).transfer(weiAmount);
    }

    receive() external payable {
        buyTokens(msg.sender);
    }

    fallback() external payable {
        buyTokens(msg.sender);
    }

    function drainRemainingTokens() public onlyOwner {
        uint256 balance = IERC20(_token).balanceOf(address(this));
        IERC20(_token).transfer(_wallet, balance);
    }

    function transferOwnership(address newOwner) public onlyOwner {
        require(newOwner != address(0));
        emit OwnershipTransferred(_owner, newOwner);
        _owner = newOwner;
    }
}
