pragma solidity ^0.8.0;

contract ProxyAdmin {
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    function owner() public view returns (address) {
        address owner_;
        assembly {
            owner_ := sload(0x33)
        }
        return owner_;
    }

    function renounceOwnership() public {
        address currentOwner;
        assembly {
            currentOwner := sload(0x33)
        }
        require(currentOwner == msg.sender, "Ownable: caller is not the owner");
        emit OwnershipTransferred(currentOwner, address(0));
        assembly {
            sstore(0x33, 0)
        }
    }

    function transferOwnership(address newOwner) public {
        address currentOwner;
        assembly {
            currentOwner := sload(0x33)
        }
        require(currentOwner == msg.sender, "Ownable: caller is not the owner");
        require(newOwner != address(0), "Ownable: new owner is the zero address");
        emit OwnershipTransferred(currentOwner, newOwner);
        assembly {
            sstore(0x33, newOwner)
        }
    }

    function upgradeProxyTo(address newImplementation) public {
        address currentOwner;
        address impl;
        assembly {
            currentOwner := sload(0x33)
            impl := sload(0x34)
        }
        require(currentOwner == msg.sender, "Ownable: caller is not the owner");
        (bool success, ) = impl.call(abi.encodeWithSelector(0x3659cfe6, newImplementation));
        require(success);
    }

    function implAddress() public view returns (address) {
        address cachedImpl;
        assembly {
            cachedImpl := sload(0x35)
        }
        return cachedImpl;
    }

    function fetchImplAddress() public {
        address impl;
        assembly {
            impl := sload(0x34)
        }
        (bool success, bytes memory data) = impl.call(abi.encodeWithSelector(0x5c60da1b));
        require(success);
        address newCachedImpl = abi.decode(data, (address));
        assembly {
            sstore(0x35, newCachedImpl)
        }
    }

    function getAdmin() public returns (address) {
        address impl;
        assembly {
            impl := sload(0x34)
        }
        (bool success, bytes memory data) = impl.call(abi.encodeWithSelector(0xf851a440));
        require(success);
        return abi.decode(data, (address));
    }

    function changeProxyAdmin(address newAdmin) public {
        address currentOwner;
        address impl;
        assembly {
            currentOwner := sload(0x33)
            impl := sload(0x34)
        }
        require(currentOwner == msg.sender, "Ownable: caller is not the owner");
        (bool success, ) = impl.call(abi.encodeWithSelector(0x8f283970, newAdmin));
        require(success);
    }
}
