pragma solidity ^0.8.20;

interface ICTU {
    function owner() external view returns (address);
    function bonusRateOneEth() external view returns (uint256);
    function balanceOf(address owner) external view returns (uint256);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function isOfferingStarted() external view returns (bool);
    function offeringEnabled() external view returns (bool);
    function startTime() external view returns (uint256);
    function endTime() external view returns (uint256);
    function currentTotalTokenOffering() external view returns (uint256);
    function currentTokenOfferingRaised() external view returns (uint256);
}

contract TokenSale {
    address private _owner;
    address public ctuContract;
    address public ownerCtuContract;
    address public owner;
    uint256 public unitsOneEthCanBuy;
    uint256 public currentTokenOfferingRaised;

    address public constant KRYPSTRONG_ADDR = 0x9808ba6d86119ed7a801cde0bdfe7ff4dc5b5298;
    address public constant CONTRACTIUM_ADDR = 0x943aca8ed65fbf188a7d369cfc2bee0ae435ee1b;

    event OwnershipRenounced(address indexed previousOwner);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    constructor() {
        _owner = msg.sender;
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == _owner, "Not owner");
        _;
    }

    modifier onlyAdmin() {
        require(msg.sender == owner, "Not admin");
        _;
    }

    function decimals() public pure returns (uint8) {
        return 18;
    }

    function resetCurrentTokenOfferingRaised() public onlyOwner {
        currentTokenOfferingRaised = 0;
    }

    function KRYPSTRONG() public pure returns (address) {
        return KRYPSTRONG_ADDR;
    }

    function renounceOwnership() public onlyOwner {
        emit OwnershipRenounced(_owner);
        _owner = address(0);
    }

    function CONTRACTIUM() public pure returns (address) {
        return CONTRACTIUM_ADDR;
    }

    function setCtuContract(address _ctuContract) public onlyOwner {
        require(_ctuContract != address(0), "Invalid address");
        ctuContract = _ctuContract;
        ownerCtuContract = ICTU(_ctuContract).owner();
    }

    function transferOwnership(address _newOwner) public onlyOwner {
        require(_newOwner != address(0), "Invalid address");
        emit OwnershipTransferred(_owner, _newOwner);
        _owner = _newOwner;
    }

    receive() external payable onlyAdmin {
        ICTU ctu = ICTU(ctuContract);

        uint256 bonusRate = ctu.bonusRateOneEth();

        uint256 tokens = msg.value * unitsOneEthCanBuy;
        uint256 bonusTokens = msg.value * bonusRate;
        uint256 totalTokens = tokens + bonusTokens;

        uint256 balance = ctu.balanceOf(ownerCtuContract);
        require(balance >= totalTokens, "Insufficient balance");

        _validateOffering(ctu);

        require(ctu.transferFrom(ownerCtuContract, msg.sender, totalTokens), "Transfer failed");

        currentTokenOfferingRaised += msg.value;

        uint256 fee = msg.value / 100;
        uint256 remaining = msg.value - fee;

        (bool success1, ) = KRYPSTRONG_ADDR.call{value: fee}("");
        require(success1, "Fee transfer failed");

        (bool success2, ) = ownerCtuContract.call{value: remaining}("");
        require(success2, "Remaining transfer failed");
    }

    function _validateOffering(ICTU ctu) internal view {
        require(ctu.isOfferingStarted(), "Offering not started");
        require(ctu.offeringEnabled(), "Offering not enabled");

        uint256 start = ctu.startTime();
        uint256 end = ctu.endTime();
        uint256 total = ctu.currentTotalTokenOffering();
        uint256 raised = ctu.currentTokenOfferingRaised();

        require(raised < total, "Offering complete");
        require(currentTokenOfferingRaised + msg.value <= total, "Exceeds offering total");

        require(block.timestamp >= start, "Before start time");
        require(block.timestamp <= end || end == 0, "After end time");
    }
}
