pragma solidity ^0.8.20;

interface IWETH {
    function balanceOf(address account) external view returns (uint256);
    function withdraw(uint256 amount) external;
}

contract SweepContract {
    // Storage layout:
    // Slot 0: owner (bits 0-159) | sweepable flag (bit 160)
    // Slot 1: weth address

    event OwnerChanged(address indexed previousOwner, address indexed newOwner);
    event Sweeped(address previousOwner, address newOwner);
    event SweepStateChange(bool previousState, bool newState);

    error InsufficientBalance();
    error CallToNonContract();
    error LowLevelCallFailed();
    error UnableToSendValue();

    constructor(address _weth) {
        assembly {
            sstore(1, _weth)
            sstore(0, caller())
        }
    }

    function _getOwner() private view returns (address owner_) {
        assembly {
            owner_ := and(sload(0), 0xffffffffffffffffffffffffffffffffffffffff)
        }
    }

    function _getSweepable() private view returns (bool sweepable_) {
        assembly {
            sweepable_ := iszero(iszero(and(shr(160, sload(0)), 0xff)))
        }
    }

    function owner() public view returns (address) {
        return _getOwner();
    }

    function isOwner() public view returns (bool) {
        return msg.sender == _getOwner();
    }

    function isSweepable() public view returns (bool) {
        return _getSweepable();
    }

    function Weth() public view returns (address weth_) {
        assembly {
            weth_ := and(sload(1), 0xffffffffffffffffffffffffffffffffffffffff)
        }
    }

    function enableSweep(bool _enable) public {
        require(msg.sender == _getOwner(), "Not owner");
        bool oldState = _getSweepable();
        emit SweepStateChange(oldState, _enable);

        uint256 value;
        assembly {
            value := sload(0)
            let masked := and(value, 0xffffffffffffffffffffffffffffffffffffffff)
            let flag := shl(160, _enable)
            sstore(0, or(masked, flag))
        }
    }

    function sweep(address newOwner_) public {
        address currentOwner = _getOwner();
        bool sweepable = _getSweepable();

        if (currentOwner == address(0)) {
            require(sweepable, "Not sweepable");
        } else {
            require(msg.sender == currentOwner, "Not owner");
        }

        require(newOwner_ != address(0), "Invalid address");

        emit Sweeped(currentOwner, newOwner_);

        assembly {
            let value := sload(0)
            let flag := and(shr(160, value), 0xff)
            sstore(0, or(shl(160, flag), newOwner_))
        }
    }

    function changeOwnership(address newOwner_) public {
        address currentOwner = _getOwner();
        require(msg.sender == currentOwner, "Not owner");
        require(newOwner_ != address(0), "Invalid address");
        require(newOwner_ != currentOwner, "Same owner");

        emit OwnerChanged(currentOwner, newOwner_);

        assembly {
            let value := sload(0)
            let flag := and(shr(160, value), 0xff)
            sstore(0, or(shl(160, flag), newOwner_))
        }
    }

    function exchangeToEthSendTo(address recipient) public {
        require(msg.sender == _getOwner(), "Not owner");

        address wethAddr = Weth();
        uint256 balance = IWETH(wethAddr).balanceOf(address(this));

        if (balance > 0) {
            IWETH(wethAddr).withdraw(balance);
        }

        uint256 ethBalance = address(this).balance;
        (bool success, ) = recipient.call{value: ethBalance}("");
        require(success, "Unable to send value, recipient may have reverted");
    }

    receive() external payable {}
}
