// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

contract ERC1155 {
    mapping(address => uint256) private _nonces;
    address private _minter;
    mapping(uint256 => string) private _names;
    mapping(uint256 => string) private _symbols;
    mapping(uint256 => string) private _uris;
    mapping(uint256 => uint256) private _totalSupplies;
    mapping(uint256 => mapping(address => uint256)) private _balances;
    mapping(address => mapping(address => bool)) private _operatorApprovals;
    mapping(address => mapping(address => mapping(uint256 => uint256))) private _allowances;

    event TransferSingle(address indexed operator, address indexed from, address indexed to, uint256 id, uint256 value);
    event TransferBatch(address indexed operator, address indexed from, address indexed to, uint256[] ids, uint256[] values);
    event Approval(address indexed account, address indexed operator, uint256 indexed id, uint256 value);
    event OperatorSet(address indexed account, address indexed operator, bool approved);

    error Panic(uint256 errorCode);
    error InsufficientAllowance();
    error InsufficientBalance();
    error BurnFromZeroAddress();
    error MintToZeroAddress();
    error TransferToZeroAddress();
    error TransferFromZeroAddress();
    error CallerNotTokenOwner();
    error CallerNotMinter();
    error MinterAlreadyInitialized();

    modifier onlyMinter() {
        if (msg.sender != _minter) revert CallerNotMinter();
        _;
    }

    function minter() external view returns (address) {
        return _minter;
    }

    function setMinter(address newMinter) external {
        if (_minter != address(0)) revert MinterAlreadyInitialized();
        _minter = newMinter;
    }

    function name(uint256 id) external view returns (string memory) {
        return _names[id];
    }

    function symbol(uint256 id) external view returns (string memory) {
        return _symbols[id];
    }

    function tokenURI(uint256 id) external view returns (string memory) {
        return _uris[id];
    }

    function totalSupply(uint256 id) external view returns (uint256) {
        return _totalSupplies[id];
    }

    function balanceOf(address account, uint256 id) external view returns (uint256) {
        return _balances[id][account];
    }

    function balanceOfBatch(address[] calldata accounts, uint256[] calldata ids) external view returns (uint256[] memory) {
        if (accounts.length != ids.length) revert();
        uint256[] memory batchBalances = new uint256[](accounts.length);
        for (uint256 i = 0; i < accounts.length;) {
            batchBalances[i] = _balances[ids[i]][accounts[i]];
            unchecked { ++i; }
        }
        return batchBalances;
    }

    function isOperator(address account, address operator) external view returns (bool) {
        return _operatorApprovals[account][operator];
    }

    function nonces(address owner) external view returns (uint256) {
        return _nonces[owner];
    }

    function allowance(address owner, address operator, uint256 id) external view returns (uint256) {
        return _allowances[owner][operator][id];
    }

    function setOperator(address operator, bool approved) external returns (bool) {
        _operatorApprovals[msg.sender][operator] = approved;
        emit OperatorSet(msg.sender, operator, approved);
        return true;
    }

    function approve(address operator, uint256 id, uint256 amount) external returns (bool) {
        _allowances[msg.sender][operator][id] = amount;
        emit Approval(msg.sender, operator, id, amount);
        return true;
    }

    function transfer(address to, uint256 id, uint256 amount, bytes calldata) external returns (bool) {
        _transfer(msg.sender, to, id, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 id, uint256 amount) external returns (bool) {
        _checkApproval(from, id, amount);
        _transfer(from, to, id, amount);
        return true;
    }

    function safeBatchTransferFrom(
        address from,
        address to,
        uint256[] calldata ids,
        uint256[] calldata amounts,
        bytes calldata
    ) external returns (bool) {
        if (ids.length != amounts.length) revert();
        for (uint256 i = 0; i < ids.length;) {
            _checkApproval(from, ids[i], amounts[i]);
            _transfer(from, to, ids[i], amounts[i]);
            unchecked { ++i; }
        }
        emit TransferBatch(msg.sender, from, to, ids, amounts);
        return true;
    }

    function mint(uint256 id, uint256 amount) external onlyMinter returns (bool) {
        if (msg.sender == address(0)) revert MintToZeroAddress();
        _balances[id][msg.sender] += amount;
        _totalSupplies[id] += amount;
        emit TransferSingle(msg.sender, address(0), msg.sender, id, amount);
        return true;
    }

    function burn(uint256 id, uint256 amount) external onlyMinter returns (bool) {
        if (msg.sender == address(0)) revert BurnFromZeroAddress();
        if (_balances[id][msg.sender] < amount) revert InsufficientBalance();
        _balances[id][msg.sender] -= amount;
        _totalSupplies[id] -= amount;
        emit TransferSingle(msg.sender, msg.sender, address(0), id, amount);
        return true;
    }

    function _checkApproval(address from, uint256 id, uint256 amount) internal {
        if (from == msg.sender) return;
        if (_operatorApprovals[from][msg.sender]) return;
        uint256 allowance_ = _allowances[from][msg.sender][id];
        if (allowance_ < amount) revert InsufficientAllowance();
        _allowances[from][msg.sender][id] = allowance_ - amount;
    }

    function _transfer(address from, address to, uint256 id, uint256 amount) internal {
        if (from == address(0)) revert TransferFromZeroAddress();
        if (to == address(0)) revert TransferToZeroAddress();
        if (_balances[id][from] < amount) revert InsufficientBalance();
        _balances[id][from] -= amount;
        _balances[id][to] += amount;
        emit TransferSingle(msg.sender, from, to, id, amount);
    }
}
