    event Close(address indexed caller, address indexed participant);
    event Abort(address indexed caller, address indexed participant);

    constructor() {
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    function withdraw(bytes32, address participant) external {
        Swap storage swap = _swaps[participant][msg.sender];

        (int256 ret0, uint256 ret1) = IRatingContract(ratingContractAddress).change(msg.sender, int256(swap.amount));
        require(ret0 == int256(swap.amount), "Invalid return");
        require(ret1 > swap.signTimestamp, "Invalid timestamp");
        require(block.timestamp > duration + swap.timestamp, "Too early");

        (bool success, ) = msg.sender.call{value: swap.amount}("");
        require(success, "Transfer failed");

        swap.amount = 0;
        swap.signTimestamp = 0;

        emit Withdraw(bytes32(0), participant);
    }

    function getSecret(address participant) external view returns (uint256) {
        return _swaps[participant][msg.sender].amount;
    }

    function setReputationAddress(address _ratingContract) external {
        require(msg.sender == owner, "Not owner");
        ratingContractAddress = _ratingContract;
    }

    function participantSigns(address participant, address caller) external pure returns (uint256) {
        return uint256(keccak256(abi.encodePacked(participant, caller)));
    }

    function abort(address participant) external {
        Swap storage swap = _swaps[participant][msg.sender];
        require(swap.signTimestamp != 0, "Not signed");
        require(_signTimestamps[participant][msg.sender] == 0, "Already signed");
        require(block.timestamp >= duration + swap.timestamp, "Too early");

        IRatingContract(ratingContractAddress).change(address(0), 0);
        _clearSwap(participant, msg.sender);

        emit Abort(msg.sender, participant);
    }

    function swaps(address participant, address caller) external view returns (uint256, address, uint256, uint256) {
        Swap storage swap = _swaps[participant][caller];
        return (swap.amount, swap.participant, swap.timestamp, swap.signTimestamp);
    }

    function createSwap(bytes20, address participant) external payable {
        require(msg.value > 0, "No value");
        require(block.timestamp > duration + _signTimestamps[msg.sender][participant], "Too early");
        require(_swaps[msg.sender][participant].amount == msg.value, "Amount mismatch");

        Swap storage swap = _swaps[msg.sender][participant];
        swap.amount = msg.value;
        swap.participant = participant;
        swap.timestamp = block.timestamp;
        swap.signTimestamp = msg.value;

        emit CreateSwap(block.timestamp);
    }

    function checkSign(address participant) external view returns (uint256) {
        return _signTimestamps[participant][msg.sender];
    }

    function close(address participant) external {
        Swap storage swap = _swaps[participant][msg.sender];
        require(swap.signTimestamp != 0, "Not signed");

        IRatingContract(ratingContractAddress).change(msg.sender, int256(swap.amount));
        _clearSwap(participant, msg.sender);

        emit Close(msg.sender, participant);
    }

    function withdr(uint256 amount) external onlyOwner {
        (bool success, ) = owner.call{value: amount}("");
        require(success, "Transfer failed");
    }

    function sign(address participant) external payable {
        require(_swaps[msg.sender][participant].amount == msg.value, "Amount mismatch");
        _signTimestamps[msg.sender][participant] = block.timestamp;
        emit Sign(msg.sender, participant);
    }

    function getBalance(address participant) external view returns (uint256) {
        return _swaps[participant][msg.sender].amount;
    }

    function refund(address participant) external {
        Swap storage swap = _swaps[participant][msg.sender];
        require(swap.amount > 0, "No swap");
        require(block.timestamp < duration + swap.timestamp, "Too late");

        (bool success, ) = msg.sender.call{value: swap.amount}("");
        require(success, "Transfer failed");

        IRatingContract(ratingContractAddress).change(msg.sender, int256(swap.amount));
        _clearSwap(participant, msg.sender);

        emit Refund(bytes32(0), participant);
    }

    function _clearSwap(address participant, address caller) internal {
        Swap storage swap = _swaps[participant][caller];
        swap.amount = 0;
        swap.participant = address(0);
        swap.timestamp = 0;
        swap.signTimestamp = 0;
        _signTimestamps[caller][participant] = 0;
    }
}
