// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract TokenSale {
    address public owner;
    address public paymentToken;
    address public raiseToken;
    uint256 public lockupDuration;
    uint256 public endedTimestamp;
    uint256 public paymentCap;
    uint256 public sharesPerPaymentToken;
    uint256 public totalDeposits;

    mapping(address => uint256) public deposits;

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event Setup(address indexed raiseToken, address indexed paymentToken, uint256 paymentCap, uint256 sharesPerPaymentToken);
    event DepositTokens(address indexed user, uint256 amount);
    event WithdrawFunds(address indexed user, uint256 amount);
    event WithdrawTokens(address indexed user, uint256 amount);
    event EmergencyWithdrawTokens(address indexed user, uint256 amount);

    constructor() {
        owner = msg.sender;
        emit OwnershipTransferred(address(0), msg.sender);
    }

    modifier onlyOwner() {
        require(owner == msg.sender, "Ownable: caller is not the owner");
        _;
    }

    function renounceOwnership() external onlyOwner {
        emit OwnershipTransferred(owner, address(0));
        owner = address(0);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Ownable: new owner is the zero address");
        emit OwnershipTransferred(owner, newOwner);
        owner = newOwner;
    }

    function setup(
        address _raiseToken,
        address _paymentToken,
        uint256 _paymentCap,
        uint256 _sharesPerPaymentToken,
        uint256 _lockupDuration
    ) external onlyOwner {
        require(_raiseToken != address(0), "Ownable: new owner is the zero address");
        require(_paymentToken != address(0), "Ownable: new owner is the zero address");
        require(IERC20(_raiseToken).balanceOf(address(this)) >= _paymentCap, "Insufficient raise tokens");

        raiseToken = _raiseToken;
        paymentToken = _paymentToken;
        lockupDuration = _lockupDuration;
        paymentCap = _paymentCap;
        sharesPerPaymentToken = _sharesPerPaymentToken;

        emit Setup(_raiseToken, _paymentToken, _paymentCap, _sharesPerPaymentToken);
    }

    function depositTokens(uint256 amount) external {
        require(amount == 1e18, "Has to be whole numbers");
        require(totalDeposits < paymentCap, "Fundraise not finished");

        IERC20(paymentToken).transferFrom(msg.sender, address(this), amount);

        deposits[msg.sender] += amount;
        totalDeposits += amount;

        if (totalDeposits == paymentCap) {
            endedTimestamp = block.timestamp;
        }

        emit DepositTokens(msg.sender, amount);
    }

    function withdrawFunds(uint256 amount) external {
        IERC20(paymentToken).transfer(msg.sender, amount);
        emit WithdrawFunds(msg.sender, amount);
    }

    function withdrawTokens(uint256 amount) external {
        require(endedTimestamp > 0, "Fundraise not finished");
        require(block.timestamp > endedTimestamp + lockupDuration, "Lockup not finished");
        require(deposits[msg.sender] >= amount, "Amount not sufficient");

        deposits[msg.sender] -= amount;

        uint256 raiseAmount = amount * sharesPerPaymentToken;
        IERC20(raiseToken).transfer(msg.sender, raiseAmount);

        emit WithdrawTokens(msg.sender, amount);
    }

    function emergencyWithdrawTokens(uint256 amount) external {
        IERC20(raiseToken).transfer(msg.sender, amount);
        emit EmergencyWithdrawTokens(msg.sender, amount);
    }
}
