// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract NFT {
    string private _name;
    string private _symbol;
    uint256 private _currentIndex;
    uint256 private _burned;
    address private _owner;
    string private _baseURI;

    mapping(uint256 => uint256) private _packedOwnerships;
    mapping(address => mapping(address => bool)) private _operatorApprovals;
    uint256 private _saleConfig;

    event Transfer(address indexed from, address indexed to, uint256 indexed tokenId);
    event Approval(address indexed owner, address indexed approved, uint256 indexed tokenId);
    event ApprovalForAll(address indexed owner, address indexed operator, bool approved);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    error InvalidQuery();
    error NotApproved();
    error NotOwner();
    error ZeroAddress();
    error InsufficientETH();
    error MintNotStarted();
    error MaxSupplyReached();
    error MaxPerAddressReached();
    error TransferFailed();
    error ContractCall();

    constructor(string memory name_, string memory symbol_) {
        _name = name_;
        _symbol = symbol_;
        _owner = msg.sender;
        emit OwnershipTransferred(address(0), msg.sender);
    }

    modifier onlyOwner() {
        if (_owner != msg.sender) revert NotOwner();
        _;
    }

    function supportsInterface(bytes4 interfaceId) public pure returns (bool) {
        return interfaceId == 0x01ffc9a7 || interfaceId == 0x80ac58cd || interfaceId == 0x5b5e139f;
    }

    function name() public view returns (string memory) {
        return _name;
    }

    function symbol() public view returns (string memory) {
        return _symbol;
    }

    function owner() public view returns (address) {
        return _owner;
    }

    function balanceOf(address owner_) public view returns (uint256) {
        if (owner_ == address(0)) revert InvalidQuery();
        return uint64(_packedOwnerships[uint256(uint160(owner_))]);
    }

    function ownerOf(uint256 tokenId) public view returns (address) {
        address owner_ = address(uint160(_packedOwnerships[tokenId]));
        if (owner_ == address(0)) revert InvalidQuery();
        return owner_;
    }

    function approve(address to, uint256 tokenId) public {
        address owner_ = ownerOf(tokenId);
        if (to == owner_) revert NotApproved();
        if (msg.sender != owner_ && !isApprovedForAll(owner_, msg.sender)) revert NotApproved();
        emit Approval(owner_, to, tokenId);
    }

    function getApproved(uint256 tokenId) public view returns (address) {
        if (!_exists(tokenId)) revert InvalidQuery();
        return address(uint160(_packedOwnerships[tokenId] >> 160));
    }

    function setApprovalForAll(address operator, bool approved) public {
        _operatorApprovals[msg.sender][operator] = approved;
        emit ApprovalForAll(msg.sender, operator, approved);
    }

    function isApprovedForAll(address owner_, address operator) public view returns (bool) {
        return _operatorApprovals[owner_][operator];
    }

    function transferFrom(address from, address to, uint256 tokenId) public {
        _transfer(from, to, tokenId);
    }

    function safeTransferFrom(address from, address to, uint256 tokenId) public {
        _transfer(from, to, tokenId);
        _checkOnERC721Received(from, to, tokenId, "");
    }

    function safeTransferFrom(address from, address to, uint256 tokenId, bytes memory data) public {
        _transfer(from, to, tokenId);
        _checkOnERC721Received(from, to, tokenId, data);
    }

    function totalSupply() public view returns (uint256) {
        return _currentIndex - _burned;
    }

    function collectionSize() public pure returns (uint256) {
        return 0;
    }

    function maxPerAddressDuringMint() public pure returns (uint256) {
        return 0;
    }

    function amountForDevs() public pure returns (uint256) {
        return 0;
    }

    function numberMinted(address owner_) public view returns (uint256) {
        return uint64(_packedOwnerships[uint256(uint160(owner_))] >> 64);
    }

    function saleConfig() public view returns (uint32, uint64) {
        uint256 config = _saleConfig;
        return (uint32(config), uint64(config >> 32));
    }

    function contractURI() public view returns (string memory) {
        return string(abi.encodePacked(_baseURI, "uri.json"));
    }

    function tokenURI(uint256 tokenId) public view returns (string memory) {
        if (!_exists(tokenId)) revert InvalidQuery();
        return string(abi.encodePacked(_baseURI, _toString(tokenId), ".json"));
    }

    function setupNonAuctionSaleInfo(uint64 price, uint32 saleStartTime) public onlyOwner {
        _saleConfig = uint256(saleStartTime) | (uint256(price) << 32);
    }

    function isPublicSaleOn() public view returns (bool) {
        (uint32 saleStartTime,) = saleConfig();
        if (saleStartTime == 0) revert MintNotStarted();
        return block.timestamp >= saleStartTime;
    }

    function mint(uint256 quantity) public payable {
        if (msg.sender != tx.origin) revert ContractCall();
        if (!isPublicSaleOn()) revert MintNotStarted();
        (, uint64 price) = saleConfig();
        if (msg.value < uint256(price) * quantity) revert InsufficientETH();
        _mint(msg.sender, quantity);
    }

    function devMint(uint256 quantity) public onlyOwner {
        if (quantity == 0) revert MaxSupplyReached();
        if (_currentIndex + quantity > _currentIndex) revert MaxSupplyReached();
        _mint(msg.sender, quantity);
    }

    function setBaseURI(string memory baseURI_) public onlyOwner {
        _baseURI = baseURI_;
    }

    function withdrawMoney() public onlyOwner {
        (bool success,) = payable(_owner).call{value: address(this).balance}("");
        if (!success) revert TransferFailed();
    }

    function renounceOwnership() public onlyOwner {
        emit OwnershipTransferred(_owner, address(0));
        _owner = address(0);
    }

    function transferOwnership(address newOwner) public onlyOwner {
        if (newOwner == address(0)) revert ZeroAddress();
        emit OwnershipTransferred(_owner, newOwner);
        _owner = newOwner;
    }

    function _exists(uint256 tokenId) internal view returns (bool) {
        return _packedOwnerships[tokenId] != 0;
    }

    function _mint(address to, uint256 quantity) internal {
        uint256 startTokenId = _currentIndex;
        for (uint256 i = 0; i < quantity; i++) {
            _packedOwnerships[startTokenId + i] = uint256(uint160(to));
            emit Transfer(address(0), to, startTokenId + i);
        }
        _currentIndex += quantity;
        uint256 packed = _packedOwnerships[uint256(uint160(to))];
        _packedOwnerships[uint256(uint160(to))] = packed + quantity + (quantity << 64);
    }

    function _transfer(address from, address to, uint256 tokenId) internal {
        address owner_ = ownerOf(tokenId);
        if (msg.sender != owner_ && !isApprovedForAll(owner_, msg.sender) && getApproved(tokenId) != msg.sender) revert NotApproved();
        if (from != owner_) revert NotApproved();
        if (to == address(0)) revert ZeroAddress();
        _packedOwnerships[tokenId] = uint256(uint160(to));
        uint256 packed = _packedOwnerships[uint256(uint160(from))];
        _packedOwnerships[uint256(uint160(from))] = packed - 1;
        packed = _packedOwnerships[uint256(uint160(to))];
        _packedOwnerships[uint256(uint160(to))] = packed + 1 + (1 << 64);
        emit Transfer(from, to, tokenId);
    }

    function _checkOnERC721Received(address from, address to, uint256 tokenId, bytes memory data) internal {
        if (to.code.length > 0) {
            try IERC721Receiver(to).onERC721Received(msg.sender, from, tokenId, data) returns (bytes4 retval) {
                if (retval != IERC721Receiver.onERC721Received.selector) revert NotApproved();
            } catch {
                revert NotApproved();
            }
        }
    }

    function _toString(uint256 value) internal pure returns (string memory) {
        if (value == 0) return "0";
        uint256 temp = value;
        uint256 digits;
        while (temp != 0) {
            digits++;
            temp /= 10;
        }
        bytes memory buffer = new bytes(digits);
        while (value != 0) {
            digits -= 1;
            buffer[digits] = bytes1(uint8(48 + uint256(value % 10)));
            value /= 10;
        }
        return string(buffer);
    }
}

interface IERC721Receiver {
    function onERC721Received(address operator, address from, uint256 tokenId, bytes memory data) external returns (bytes4);
}
