        _owners[tokenId] = to;
        _balances[to] += 1;
        _ownedTokens[to][_ownedTokensIndex[to][0] == 0 && _balances[to] == 1 ? 0 : _balances[to] - 1] = tokenId;
        _ownedTokensIndex[to][tokenId] = _balances[to] - 1;
        _allTokens.push(tokenId);
        _allTokensIndex[tokenId] = _allTokens.length - 1;
        emit Transfer(address(0), to, tokenId);
    }

    function _transfer(address from, address to, uint256 tokenId) internal {
        require(ownerOf(tokenId) == from, "ERC721: transfer of token that is not own");
        require(to != address(0), "ERC721: transfer to the zero address");
        _approve(address(0), tokenId);
        _balances[from] -= 1;
        _balances[to] += 1;
        _owners[tokenId] = to;
        uint256 lastTokenIndex = _balances[from];
        uint256 tokenIndex = _ownedTokensIndex[from][tokenId];
        if (tokenIndex != lastTokenIndex) {
            uint256 lastTokenId = _ownedTokens[from][lastTokenIndex];
            _ownedTokens[from][tokenIndex] = lastTokenId;
            _ownedTokensIndex[from][lastTokenId] = tokenIndex;
        }
        delete _ownedTokens[from][lastTokenIndex];
        delete _ownedTokensIndex[from][tokenId];
        _ownedTokens[to][_balances[to] - 1] = tokenId;
        _ownedTokensIndex[to][tokenId] = _balances[to] - 1;
        emit Transfer(from, to, tokenId);
    }

    function _safeTransfer(address from, address to, uint256 tokenId, bytes memory data) internal {
        _transfer(from, to, tokenId);
        require(_checkOnERC721Received(from, to, tokenId, data), "ERC721: transfer to non ERC721Receiver implementer");
    }

    function _checkOnERC721Received(address from, address to, uint256 tokenId, bytes memory data) private returns (bool) {
        if (to.code.length > 0) {
            try IERC721Receiver(to).onERC721Received(msg.sender, from, tokenId, data) returns (bytes4 retval) {
                return retval == IERC721Receiver.onERC721Received.selector;
            } catch (bytes memory reason) {
                if (reason.length == 0) {
                    revert("ERC721: transfer to non ERC721Receiver implementer");
                } else {
                    assembly { revert(add(32, reason), mload(reason)) }
                }
            }
        }
        return true;
    }

    function toString(uint256 value) internal pure returns (string memory) {
        if (value == 0) return "0";
        uint256 temp = value;
        uint256 digits;
        while (temp != 0) {
            digits++;
            temp /= 10;
        }
        bytes memory buffer = new bytes(digits);
        while (value != 0) {
            digits -= 1;
            buffer[digits] = bytes1(uint8(48 + uint256(value % 10)));
            value /= 10;
        }
        return string(buffer);
    }

    function _base64(bytes memory data) internal pure returns (string memory) {
        bytes memory table = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        uint256 len = data.length;
        if (len == 0) return "";
        uint256 encodedLen = 4 * ((len + 2) / 3);
        bytes memory result = new bytes(encodedLen);
        uint256 resultIdx = 0;
        for (uint256 i = 0; i < len; i += 3) {
            uint256 n = uint256(uint8(data[i])) << 16;
            if (i + 1 < len) n |= uint256(uint8(data[i + 1])) << 8;
            if (i + 2 < len) n |= uint256(uint8(data[i + 2]));
            result[resultIdx++] = table[n >> 18];
            result[resultIdx++] = table[(n >> 12) & 0x3F];
            if (i + 1 < len) result[resultIdx++] = table[(n >> 6) & 0x3F];
            else result[resultIdx++] = '=';
            if (i + 2 < len) result[resultIdx++] = table[n & 0x3F];
            else result[resultIdx++] = '=';
        }
        return string(result);
    }
}

interface IERC721Receiver {
    function onERC721Received(address operator, address from, uint256 tokenId, bytes calldata data) external returns (bytes4);
}
