    event ClaimedMultiple(uint256[] mintPassIds, address indexed account, uint256[] amounts);

    modifier onlyOwner() {
        require(_owner == msg.sender, "Ownable: caller is not the owner");
        _;
    }

    modifier onlyRole(bytes32 role) {
        require(hasRole(msg.sender, role), "Caller does not have permission");
        _;
    }

    modifier whenNotPaused() {
        require(!_paused, "Pausable: paused");
        _;
    }

    modifier whenPaused() {
        require(_paused, "Pausable: not paused");
        _;
    }

    constructor() {
        _owner = msg.sender;
        _roleAdmin[DEFAULT_ADMIN_ROLE] = DEFAULT_ADMIN_ROLE;
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(HABIBI_OPERATOR_ROLE, msg.sender);
    }

    function supportsInterface(bytes4 interfaceId) public pure override returns (bool) {
        return interfaceId == type(IERC1155).interfaceId ||
               interfaceId == type(IERC165).interfaceId ||
               interfaceId == 0xd9b67a26 ||
               interfaceId == 0x0e89341c;
    }

    function owner() public view returns (address) {
        return _owner;
    }

    function transferOwnership(address newOwner) public onlyOwner {
        require(newOwner != address(0), "Ownable: new owner is the zero address");
        address oldOwner = _owner;
        _owner = newOwner;
        emit OwnershipTransferred(oldOwner, newOwner);
    }

    function renounceOwnership() public onlyOwner {
        address oldOwner = _owner;
        _owner = address(0);
        emit OwnershipTransferred(oldOwner, address(0));
    }

    function paused() public view returns (bool) {
        return _paused;
    }

    function pause() public onlyOwner whenNotPaused {
        _paused = true;
        emit Paused(msg.sender);
    }

    function unpause() public onlyOwner whenPaused {
        _paused = false;
        emit Unpaused(msg.sender);
    }

    function hasRole(address account, bytes32 role) public view returns (bool) {
        return _roles[role][account];
    }

    function getRoleAdmin(bytes32 role) public view returns (bytes32) {
        return _roleAdmin[role];
    }

    function grantRole(bytes32 role, address account) public onlyOwner {
        _grantRole(account, role);
    }

    function revokeRole(bytes32 role, address account) public onlyOwner {
        _revokeRole(account, role);
    }

    function renounceRole(bytes32 role, address account) public {
        require(account == msg.sender, "AccessControl: can only renounce roles for self");
        _revokeRole(account, role);
    }

    function _grantRole(address account, bytes32 role) internal {
        _roles[role][account] = true;
        emit RoleGranted(account, role, msg.sender);
    }

    function _revokeRole(address account, bytes32 role) internal {
        _roles[role][account] = false;
        emit RoleRevoked(account, role, msg.sender);
    }

    function balanceOf(address account, uint256 id) public view override returns (uint256) {
        require(account != address(0), "ERC1155: balance query for the zero address");
        return _balances[id][account];
    }

    function balanceOfBatch(address[] memory accounts, uint256[] memory ids) public view override returns (uint256[] memory) {
        require(accounts.length == ids.length, "ERC1155: accounts and ids length mismatch");
        uint256[] memory batchBalances = new uint256[](accounts.length);
        for (uint256 i = 0; i < accounts.length; ++i) {
            batchBalances[i] = balanceOf(accounts[i], ids[i]);
        }
        return batchBalances;
    }

    function setApprovalForAll(address operator, bool approved) public override {
        require(msg.sender != operator, "ERC1155: setting approval status for self");
        _operatorApprovals[msg.sender][operator] = approved;
        emit ApprovalForAll(msg.sender, operator, approved);
    }

    function isApprovedForAll(address account, address operator) public view override returns (bool) {
        return _operatorApprovals[account][operator];
    }

    function safeTransferFrom(address from, address to, uint256 id, uint256 amount, bytes memory data) public override whenNotPaused {
        require(to != address(0), "ERC1155: transfer to the zero address");
        require(from == msg.sender || isApprovedForAll(from, msg.sender), "ERC1155: caller is not owner nor approved");

        _balances[id][from] -= amount;
        _balances[id][to] += amount;

        emit TransferSingle(msg.sender, from, to, id, amount);

        _doSafeTransferAcceptanceCheck(msg.sender, from, to, id, amount, data);
    }

    function safeBatchTransferFrom(address from, address to, uint256[] memory ids, uint256[] memory amounts, bytes memory data) public override whenNotPaused {
        require(ids.length == amounts.length, "ERC1155: ids and amounts length mismatch");
        require(to != address(0), "ERC1155: transfer to the zero address");
        require(from == msg.sender || isApprovedForAll(from, msg.sender), "ERC1155: caller is not owner nor approved");

        for (uint256 i = 0; i < ids.length; ++i) {
            _balances[ids[i]][from] -= amounts[i];
            _balances[ids[i]][to] += amounts[i];
        }

        emit TransferBatch(msg.sender, from, to, ids, amounts);
        _doSafeBatchTransferAcceptanceCheck(msg.sender, from, to, ids, amounts, data);
    }

    function _doSafeTransferAcceptanceCheck(address operator, address from, address to, uint256 id, uint256 amount, bytes memory data) private {
        if (to.code.length > 0) {
            try IERC1155Receiver(to).onERC1155Received(operator, from, id, amount, data) returns (bytes4 response) {
                require(response == IERC1155Receiver.onERC1155Received.selector, "ERC1155: ERC1155Receiver rejected tokens");
            } catch Error(string memory reason) {
                revert(reason);
            } catch {
                revert("ERC1155: transfer to non-ERC1155Receiver implementer");
            }
        }
    }

    function _doSafeBatchTransferAcceptanceCheck(address operator, address from, address to, uint256[] memory ids, uint256[] memory amounts, bytes memory data) private {
        if (to.code.length > 0) {
            try IERC1155Receiver(to).onERC1155BatchReceived(operator, from, ids, amounts, data) returns (bytes4 response) {
                require(response == IERC1155Receiver.onERC1155BatchReceived.selector, "ERC1155: ERC1155Receiver rejected tokens");
            } catch Error(string memory reason) {
                revert(reason);
            } catch {
                revert("ERC1155: transfer to non-ERC1155Receiver implementer");
            }
        }
    }

    function name() public view returns (string memory) {
        return _name;
    }

    function name_() public view returns (string memory) {
        return _name;
    }

    function symbol() public view returns (string memory) {
        return _symbol;
    }

    function symbol_() public view returns (string memory) {
        return _symbol;
    }

    function uri(uint256 id) public view returns (string memory) {
        return _mintPasses[id].uri;
    }

    function contractURI() public view returns (string memory) {
        return _contractURI;
    }

    function _contractURI() public view returns (string memory) {
        return _contractURI;
    }

    function setContractURI(string memory newURI) public onlyOwner {
        _contractURI = newURI;
    }

    function setURI(string memory newURI) public onlyOwner {
        _baseURI = newURI;
    }

    function totalSupply(uint256 id) public view returns (uint256) {
        return _totalSupply[id];
    }

    function exists(uint256 id) public view returns (bool) {
        return _totalSupply[id] > 0;
    }

    function mint(address to, uint256 id, uint256 amount) public onlyRole(HABIBI_OPERATOR_ROLE) {
        require(to != address(0), "ERC1155: mint to the zero address");
        _balances[id][to] += amount;
        _totalSupply[id] += amount;
        emit TransferSingle(msg.sender, address(0), to, id, amount);
    }

    function mintBatch(address to, uint256[] memory ids, uint256[] memory amounts) public onlyRole(HABIBI_OPERATOR_ROLE) {
        require(to != address(0), "ERC1155: mint to the zero address");
        for (uint256 i = 0; i < ids.length; ++i) {
            _balances[ids[i]][to] += amounts[i];
            _totalSupply[ids[i]] += amounts[i];
        }
        emit TransferBatch(msg.sender, address(0), to, ids, amounts);
    }

    function burn(address from, uint256 id, uint256 amount) public {
        require(from == msg.sender || isApprovedForAll(from, msg.sender), "ERC1155: caller is not owner nor approved");
        _balances[id][from] -= amount;
        _totalSupply[id] -= amount;
        emit TransferSingle(msg.sender, from, address(0), id, amount);
    }

    function burnBatch(address from, uint256[] memory ids, uint256[] memory amounts) public {
        require(from == msg.sender || isApprovedForAll(from, msg.sender), "ERC1155: caller is not owner nor approved");
        for (uint256 i = 0; i < ids.length; ++i) {
            _balances[ids[i]][from] -= amounts[i];
            _totalSupply[ids[i]] -= amounts[i];
        }
        emit TransferBatch(msg.sender, from, address(0), ids, amounts);
    }

    function addMintPass(bytes32 merkleRoot, uint256 startTime, uint256 endTime, uint256 price, uint256 maxSupply, uint256 maxPerTx, string memory uri_, address paymentReceiver, uint256 mintPassId) public onlyOwner {
        require(startTime < endTime, "addMintPass: open window must be before close window");
        require(endTime > 0, "addMintPass: window cannot be 0");

        MintPass storage mp = _mintPasses[mintPassId];
        mp.merkleRoot = merkleRoot;
        mp.startTime = startTime;
        mp.endTime = endTime;
        mp.price = price;
        mp.maxSupply = maxSupply;
        mp.maxPerTx = maxPerTx;
        mp.uri = uri_;
        mp.paymentReceiver = paymentReceiver;
    }

    function editMintPass(bytes32 merkleRoot, uint256 startTime, uint256 endTime, uint256 price, uint256 maxSupply, uint256 maxPerTx, string memory uri_, address paymentReceiver, uint256 mintPassId, bool isDutchAuction, uint256 mintPassCounter) public onlyOwner {
        require(startTime < endTime, "editMintPass: open window must be before close window");
        require(endTime > 0, "editMintPass: window cannot be 0");

        MintPass storage mp = _mintPasses[mintPassId];
        mp.merkleRoot = merkleRoot;
        mp.startTime = startTime;
        mp.endTime = endTime;
        mp.price = price;
        mp.maxSupply = maxSupply;
        mp.maxPerTx = maxPerTx;
        mp.uri = uri_;
        mp.paymentReceiver = paymentReceiver;
        mp.isDutchAuction = isDutchAuction;
    }

    function editMintPassWhiteListMerkleRoot(bytes32 merkleRoot, uint256 mintPassId) public onlyOwner {
        _mintPasses[mintPassId].merkleRoot = merkleRoot;
    }

    function setDutchAuctionSettings(uint256 mintPassId, bool isDutchAuction, uint256 startPrice, uint256 endPrice, uint256 duration, uint256 priceChangeInterval, uint256 startTime) public onlyOwner {
        MintPass storage mp = _mintPasses[mintPassId];
        mp.isDutchAuction = isDutchAuction;
        mp.startPrice = startPrice;
        mp.endPrice = endPrice;
        mp.duration = duration;
        mp.priceChangeInterval = priceChangeInterval;
        mp.startTime = startTime;
    }

    function getPrice(uint256 mintPassId) public view returns (uint256) {
        MintPass storage mp = _mintPasses[mintPassId];
        if (!mp.isDutchAuction) {
            return mp.price;
        }

        uint256 timeElapsed = block.timestamp - mp.startTime;
        if (timeElapsed >= mp.duration) {
            return mp.endPrice;
        }

        uint256 priceDecrease = (mp.startPrice - mp.endPrice) * timeElapsed / mp.duration;
        return mp.startPrice - priceDecrease;
    }

    function isSaleOpen(uint256 mintPassId) public view returns (bool) {
        MintPass storage mp = _mintPasses[mintPassId];
        return block.timestamp >= mp.startTime && block.timestamp <= mp.endTime;
    }

    function turnSaleOn(uint256 mintPassId) public onlyOwner {
        _mintPasses[mintPassId].startTime = block.timestamp;
    }

    function turnSaleOff(uint256 mintPassId) public onlyOwner {
        _mintPasses[mintPassId].endTime = block.timestamp;
    }

    function getRemainingPassSupply(uint256 mintPassId) public view returns (uint256) {
        return _mintPasses[mintPassId].maxSupply - _totalSupply[mintPassId];
    }

    function getClaimedMps(uint256 mintPassId, address account) public view returns (uint256) {
        return _claimedMps[mintPassId][account];
    }

    function getTokenSupply(uint256 id) public view returns (uint256) {
        return _totalSupply[id];
    }

    function getDutchTiers(uint256 mintPassId) public view returns (uint256, uint256, uint256, uint256, uint256, uint256) {
        MintPass storage mp = _mintPasses[mintPassId];
        return (mp.startPrice, mp.endPrice, mp.duration, mp.priceChangeInterval, mp.startTime, mp.endTime);
    }

    function getRemainingTimeBeforeNextPricingChange(uint256 mintPassId) public view returns (uint256) {
        MintPass storage mp = _mintPasses[mintPassId];
        if (!mp.isDutchAuction) return 0;

        uint256 timeElapsed = (block.timestamp - mp.startTime) % mp.priceChangeInterval;
        return mp.priceChangeInterval - timeElapsed;
    }

    function claim(uint256 mintPassId, uint256 amount, uint256 maxAmount, bytes32[] memory merkleProof) public payable whenNotPaused {
        MintPass storage mp = _mintPasses[mintPassId];

        require(mp.isDutchAuction || mp.price > 0, "Sale is not a dutch auction");
        require(block.timestamp >= mp.startTime && block.timestamp <= mp.endTime, "Claim: time window closed");

        uint256 price = getPrice(mintPassId);
        require(msg.value >= price * amount, "Claim: Ether value incorrect");
        require(amount <= mp.maxPerTx, "Claim: Not allowed to claim given amount");
        require(_claimedMps[mintPassId][msg.sender] + amount <= maxAmount, "Claim: Not allowed to claim that much");
        require(_totalSupply[mintPassId] + amount <= mp.maxSupply, "Purchase would exceed max supply");

        bytes32 leaf = keccak256(abi.encodePacked(msg.sender, maxAmount));
        require(_verifyMerkleProof(merkleProof, mp.merkleRoot, leaf), "MerkleDistributor: Invalid proof");

        _claimedMps[mintPassId][msg.sender] += amount;
        _balances[mintPassId][msg.sender] += amount;
        _totalSupply[mintPassId] += amount;

        emit TransferSingle(msg.sender, address(0), msg.sender, mintPassId, amount);
        emit Claimed(mintPassId, msg.sender, amount);

        uint256 excess = msg.value - (price * amount);
        if (excess > 0) {
            (bool success, ) = payable(msg.sender).call{value: excess}("");
            require(success, "Error returning excess payment");
        }

        if (mp.paymentReceiver != address(0)) {
            (bool success, ) = payable(mp.paymentReceiver).call{value: price * amount}("");
            require(success, "Error returning excess payment");
        }
    }

    function claimMultiple(uint256[] memory mintPassIds, uint256[] memory amounts, uint256[] memory maxAmounts, bytes32[][] memory merkleProofs) public payable whenNotPaused {
        require(mintPassIds.length == amounts.length && amounts.length == maxAmounts.length, "One or more claims are invalid");

        for (uint256 i = 0; i < mintPassIds.length; ++i) {
            claim(mintPassIds[i], amounts[i], maxAmounts[i], merkleProofs[i]);
        }

        emit ClaimedMultiple(mintPassIds, msg.sender, amounts);
    }

    function _verifyMerkleProof(bytes32[] memory proof, bytes32 root, bytes32 leaf) internal pure returns (bool) {
        for (uint256 i = 0; i < proof.length; ++i) {
            leaf = leaf < proof[i] ? keccak256(abi.encodePacked(leaf, proof[i])) : keccak256(abi.encodePacked(proof[i], leaf));
        }
        return leaf == root;
    }

    function mintPasses(uint256 mintPassId) public view returns (uint256, uint256, uint256, uint256, uint256, uint256, uint256, uint256, uint256, bool) {
        MintPass storage mp = _mintPasses[mintPassId];
        return (mp.startTime, mp.endTime, mp.price, mp.maxSupply, mp.maxPerTx, mp.startPrice, mp.endPrice, mp.duration, mp.priceChangeInterval, mp.isDutchAuction);
    }

    function makeLeaf(address account, uint256 maxAmount) public pure returns (bytes32) {
        return keccak256(abi.encodePacked(account, maxAmount));
    }

    function verifyMerkleProof(bytes32[] memory proof, uint256 maxAmount, uint256 mintPassId) public view returns (bool) {
        bytes32 leaf = keccak256(abi.encodePacked(msg.sender, maxAmount));
        return _verifyMerkleProof(proof, _mintPasses[mintPassId].merkleRoot, leaf);
    }

    function promoteTeamMember(address account) public onlyOwner {
        _grantRole(account, HABIBI_OPERATOR_ROLE);
    }

    function demoteTeamMember(address account) public onlyOwner {
        _revokeRole(account, HABIBI_OPERATOR_ROLE);
    }

    function withdrawEther(address to, uint256 amount) public onlyOwner {
        (bool success, ) = payable(to).call{value: amount}("");
        require(success, "Withdraw failed");
    }

    function burnFromRedeem(address from, uint256 id, uint256 amount) public onlyRole(HABIBI_OPERATOR_ROLE) {
        require(from == msg.sender || isApprovedForAll(from, msg.sender), "Burnable: Only allowed from redeem");
        _balances[id][from] -= amount;
        _totalSupply[id] -= amount;
        emit TransferSingle(msg.sender, from, address(0), id, amount);
    }

    function onERC1155Received(address, address, uint256, uint256, bytes memory) public pure returns (bytes4) {
        return this.onERC1155Received.selector;
    }

    function onERC1155BatchReceived(address, address, uint256[] memory, uint256[] memory, bytes memory) public pure returns (bytes4) {
        return this.onERC1155BatchReceived.selector;
    }

    receive() external payable {}
}
