// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract TimelockController {
    bytes32 public constant TIMELOCK_ADMIN_ROLE = 0xd8aa0f3194971a2a116679f7c2090f6939c8d4e01a2a8d7e41d55e5351469e63;
    bytes32 public constant PROPOSER_ROLE = 0xb09aa5aeb3702cfd50b6b62bc4532604938f21248a27a1d5ca736082b6819cc1;
    bytes32 public constant EXECUTOR_ROLE = 0x5f58e3a2316349923ce3780f8d587db2d72378aed66a8261c916544fa6846ca5;
    bytes32 public constant CANCELLER_ROLE = 0xfd643c72710c63c0180259aba6b2d05451e3591a24e58b62239378085726f783;
    bytes32 public constant DEFAULT_ADMIN_ROLE = 0x00;

    event MinDelayChange(uint256 oldDuration, uint256 newDuration);
    event RoleGranted(bytes32 indexed role, address indexed account, address indexed sender);
    event RoleRevoked(bytes32 indexed role, address indexed account, address indexed sender);
    event CallScheduled(bytes32 indexed id, uint256 indexed index, address target, uint256 value, bytes data, bytes32 predecessor, uint256 delay);
    event CallExecuted(bytes32 indexed id, uint256 indexed index, address target, uint256 value, bytes data);
    event Cancelled(bytes32 indexed id);

    struct RoleData {
        mapping(address => bool) members;
        bytes32 adminRole;
    }

    mapping(bytes32 => RoleData) private _roles;
    mapping(bytes32 => uint256) private _timestamps;
    uint256 private _minDelay;

    constructor(uint256 minDelay, address[] memory proposers, address[] memory executors, address admin) {
        _minDelay = minDelay;
        _roles[TIMELOCK_ADMIN_ROLE].adminRole = TIMELOCK_ADMIN_ROLE;
        _roles[PROPOSER_ROLE].adminRole = TIMELOCK_ADMIN_ROLE;
        _roles[EXECUTOR_ROLE].adminRole = TIMELOCK_ADMIN_ROLE;
        _roles[CANCELLER_ROLE].adminRole = TIMELOCK_ADMIN_ROLE;
        if (admin != address(0)) {
            _grantRole(TIMELOCK_ADMIN_ROLE, admin);
        }
        for (uint256 i = 0; i < proposers.length; ++i) {
            _grantRole(PROPOSER_ROLE, proposers[i]);
        }
        for (uint256 i = 0; i < executors.length; ++i) {
            _grantRole(EXECUTOR_ROLE, executors[i]);
        }
        _grantRole(CANCELLER_ROLE, address(this));
    }

    receive() external payable {}

    function getMinDelay() external view returns (uint256) {
        return _minDelay;
    }

    function hashOperation(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt) public pure returns (bytes32 hash) {
        hash = keccak256(abi.encode(target, value, data, predecessor, salt));
    }

    function hashOperationBatch(address[] calldata targets, uint256[] calldata values, bytes[] calldata payloads, bytes32 predecessor, bytes32 salt) public pure returns (bytes32 hash) {
        hash = keccak256(abi.encode(targets, values, payloads, predecessor, salt));
    }

    function schedule(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) external {
        require(hasRole(PROPOSER_ROLE, msg.sender), "AccessControl: account is missing role");
        bytes32 id = hashOperation(target, value, data, predecessor, salt);
        _schedule(id, delay);
        emit CallScheduled(id, 0, target, value, data, predecessor, delay);
    }

    function scheduleBatch(address[] calldata targets, uint256[] calldata values, bytes[] calldata payloads, bytes32 predecessor, bytes32 salt, uint256 delay) external {
        require(hasRole(PROPOSER_ROLE, msg.sender), "AccessControl: account is missing role");
        bytes32 id = hashOperationBatch(targets, values, payloads, predecessor, salt);
        _schedule(id, delay);
        for (uint256 i = 0; i < targets.length; ++i) {
            emit CallScheduled(id, i, targets[i], values[i], payloads[i], predecessor, delay);
        }
    }

    function _schedule(bytes32 id, uint256 delay) private {
        require(_timestamps[id] == 0, "TimelockController: operation already scheduled");
        require(delay >= _minDelay, "TimelockController: insufficient delay");
        _timestamps[id] = block.timestamp + delay;
    }

    function execute(address target, uint256 value, bytes calldata payload, bytes32 predecessor, bytes32 salt) external payable {
        require(hasRole(EXECUTOR_ROLE, msg.sender) || msg.sender == address(this), "AccessControl: account is missing role");
        bytes32 id = hashOperation(target, value, payload, predecessor, salt);
        _call(id, 0, target, value, payload);
    }

    function executeBatch(address[] calldata targets, uint256[] calldata values, bytes[] calldata payloads, bytes32 predecessor, bytes32 salt) external payable {
        require(hasRole(EXECUTOR_ROLE, msg.sender) || msg.sender == address(this), "AccessControl: account is missing role");
        bytes32 id = hashOperationBatch(targets, values, payloads, predecessor, salt);
        for (uint256 i = 0; i < targets.length; ++i) {
            _call(id, i, targets[i], values[i], payloads[i]);
        }
    }

    function _call(bytes32 id, uint256 index, address target, uint256 value, bytes calldata payload) private {
        require(isOperationReady(id), "TimelockController: operation is not ready");
        _timestamps[id] = 1;
        (bool success, bytes memory result) = target.call{value: value}(payload);
        if (!success) {
            if (result.length > 0) {
                assembly { revert(add(result, 32), mload(result)) }
            } else {
                revert("TimelockController: underlying transaction reverted");
            }
        }
        emit CallExecuted(id, index, target, value, payload);
    }

    function cancel(bytes32 id) external {
        require(hasRole(CANCELLER_ROLE, msg.sender), "AccessControl: account is missing role");
        require(isOperation(id), "TimelockController: operation cannot be cancelled");
        delete _timestamps[id];
        emit Cancelled(id);
    }

    function isOperation(bytes32 id) public view returns (bool) {
        return _timestamps[id] > 0;
    }

    function isOperationPending(bytes32 id) public view returns (bool) {
        return _timestamps[id] > 1;
    }

    function isOperationReady(bytes32 id) public view returns (bool) {
        uint256 timestamp = _timestamps[id];
        return timestamp > 1 && timestamp <= block.timestamp;
    }

    function isOperationDone(bytes32 id) public view returns (bool) {
        return _timestamps[id] == 1;
    }

    function getTimestamp(bytes32 id) public view returns (uint256) {
        return _timestamps[id];
    }

    function updateDelay(uint256 newDelay) external {
        require(msg.sender == address(this), "TimelockController: caller must be timelock");
        emit MinDelayChange(_minDelay, newDelay);
        _minDelay = newDelay;
    }

    function hasRole(bytes32 role, address account) public view returns (bool) {
        return _roles[role].members[account];
    }

    function getRoleAdmin(bytes32 role) public view returns (bytes32) {
        return _roles[role].adminRole;
    }

    function grantRole(bytes32 role, address account) external {
        require(hasRole(_roles[role].adminRole, msg.sender), "AccessControl: account is missing role");
        _grantRole(role, account);
    }

    function revokeRole(bytes32 role, address account) external {
        require(hasRole(_roles[role].adminRole, msg.sender), "AccessControl: account is missing role");
        _revokeRole(role, account);
    }

    function renounceRole(bytes32 role, address account) external {
        require(account == msg.sender, "AccessControl: can only renounce roles for self");
        _revokeRole(role, account);
    }

    function _grantRole(bytes32 role, address account) private {
        if (!hasRole(role, account)) {
            _roles[role].members[account] = true;
            emit RoleGranted(role, account, msg.sender);
        }
    }

    function _revokeRole(bytes32 role, address account) private {
        if (hasRole(role, account)) {
            _roles[role].members[account] = false;
            emit RoleRevoked(role, account, msg.sender);
        }
    }

    function supportsInterface(bytes4 interfaceId) public pure returns (bool) {
        return interfaceId == 0x01ffc9a7 || interfaceId == 0x150b7a02 || interfaceId == 0x4e2312e0;
    }

    function onERC721Received(address, address, uint256, bytes calldata) external pure returns (bytes4) {
        return 0x150b7a02;
    }

    function onERC1155Received(address, address, uint256, uint256, bytes calldata) external pure returns (bytes4) {
        return 0xf23a6e61;
    }

    function onERC1155BatchReceived(address, address, uint256[] calldata, uint256[] calldata, bytes calldata) external pure returns (bytes4) {
        return 0xbc197c81;
    }
}
