        if (tokens.length != ratios.length) revert UnitProtocolArrayLengthMismatch();
        for (uint256 i = 0; i < tokens.length; i++) {
            IVaultParameters(vaultParameters).setLiquidationRatio(tokens[i], ratios[i]);
        }
    }

    function setDevaluationPeriods(address[] calldata tokens, uint256[] calldata periods) external onlyManager {
        if (tokens.length != periods.length) revert UnitProtocolArrayLengthMismatch();
