            info.amount,
            info.totalLocked,
            info.lockedAmount,
            info.timestamps,
            info.amounts,
            info.isLocked
        );
    }

    function transferLock(
        address to,
        uint256 amount,
        uint256[] memory amounts_,
        uint256[] memory timestamps
    ) external onlyGovernance {
        require(to != address(0), "The recipient's address cannot be 0x0");
        require(amount > 0, "Amount has to be greater than 0");
        require(amounts_.length == timestamps.length, "Length of amounts & length of timestamps must match");

        uint256 sum;
        for (uint256 i = 0; i < amounts_.length; i++) {
