        info.amount = amount;
        info.totalLocked = amount;
        info.lockedAmount = amount;
        info.lockCount = amounts_.length;
        info.timestamps = timestamps;
        info.amounts = amounts_;
        info.isLocked = true;

        _balances[to] += amount;
        _totalSupply += amount;

        emit Transfer(address(0), to, amount);
        emit Lock(to, amount);
    }

