        require(_lockInfo[msg.sender].isLocked, "Your wallet is not locked");

        LockInfo storage info = _lockInfo[msg.sender];
        uint256 unlockedAmount;

        for (uint256 i = 0; i < info.lockCount; i++) {
            if (block.timestamp >= info.timestamps[i]) {
                unlockedAmount += info.amounts[i];
            }
        }

        if (unlockedAmount > 0) {
            info.lockedAmount -= unlockedAmount;
            if (info.lockedAmount == 0) {
                info.isLocked = false;
            }
            emit Unlock(msg.sender, unlockedAmount);
        }
    }

    function _transfer(address from, address to, uint256 amount) internal {
        require(from != address(0), "ERC20: transfer from the zero address");
        require(to != address(0), "ERC20: transfer to the zero address");

        uint256 fromBalance = _balances[from];
