contract ERC1155Predicate {
    bytes32 public constant MANAGER_ROLE = keccak256("MANAGER_ROLE");
    bytes32 public constant DEFAULT_ADMIN_ROLE = bytes32(0);

    bytes4 private constant ERC1155_RECEIVED = bytes4(0xf23a6e61);
    bytes4 private constant ERC1155_BATCH_RECEIVED = bytes4(0xbc197c81);

    event RoleGranted(bytes32 indexed role, address indexed account, address indexed sender);
    event RoleRevoked(bytes32 indexed role, address indexed account, address indexed sender);
    event LockedBatchERC1155(address indexed depositor, address indexed depositReceiver, address indexed rootToken, uint256[] ids, uint256[] amounts);

    mapping(bytes32 => mapping(address => bool)) private _roles;
    mapping(bytes32 => uint256) private _roleCount;
    mapping(bytes32 => bytes32) private _adminRoles;

    bool private _initialized;

    modifier onlyManager() {
        require(_hasRole(MANAGER_ROLE, msg.sender), "sender must be manager");
        _;
    }

    function initialize(address manager) external {
        require(!_initialized, "already initialized");
        _initialized = true;
        _setupRole(DEFAULT_ADMIN_ROLE, manager);
        _setupRole(MANAGER_ROLE, manager);
    }

    function _setupRole(bytes32 role, address account) internal {
        _grantRole role, account);
        _adminRoles[role] = DEFAULT_ADMIN_ROLE;
    }

    function _hasRole(bytes32 role, address account) internal view returns (bool) {
        return _roles[role][account];
    }

    function hasRole(bytes32 role, address account) external view returns (bool) {
        return _hasRole role, account);
    }

    function _grantRole(bytes32 role, address account) internal {
        if (!_hasRole role, account)) {
            _roles[role][account] = true;
            _roleCount[role]++;
            emit RoleGranted role, account, msg.sender);
        }
    }

    function grantRole(bytes32 role, address account) external {
        require(_hasRole(getRoleAdmin role), "AccessControl: sender must be an admin");
        _grantRole role, account);
    }

    function _revokeRole(bytes32 role, address account) internal {
        if (_hasRole role, account)) {
            _roles[role][account] = false;
            _roleCount[role]--;
            emit RoleRevoked role, account, msg.sender);
        }
    }

    function revokeRole(bytes32 role, address account) external {
        require(_hasRole(getRoleAdmin role), "AccessControl: sender must be an admin");
        _revokeRole role, account);
    }

    function renounceRole(bytes32 role, address account) external {
        require(msg.sender == account, "AccessControl: can only renounce roles for self");
        _revokeRole role, account);
    }

    function getRoleAdmin(bytes32 role) public view returns (bytes32) {
        bytes32 admin = _adminRoles[role];
        return admin == bytes32(0) ? DEFAULT_ADMIN_ROLE : admin;
    }

    function getRoleMemberCount(bytes32 role) external view returns (uint256) {
        return _roleCount[role];
    }

    function getRoleMember(bytes32 role, uint256 index) external view returns (address) {
        uint256 count;
        for (uint256 i = 0; i < 2**160; i++) {
            if (_hasRole role, address(uint160(i)))) {
                if (count == index) return address(uint160(i));
                count++;
            }
        }
        return address(0);
    }

    function lockTokens(
        address depositor,
        address depositReceiver,
        address rootToken,
        bytes calldata data
    ) external onlyManager {
        (uint256[] memory ids, uint256[] memory amounts, bytes memory metaData) = 
            abi.decode(data, (uint256[], uint256[], bytes));

        bytes memory callData = abi.encodeWithSelector(
            bytes4(0x2eb2c2d6),
            depositor,
            address(this),
            ids,
            amounts,
            metaData
        );

        (bool success, ) = rootToken.call(callData);
        require(success, "safeBatchTransferFrom failed");

        emit LockedBatchERC1155(depositor, depositReceiver, rootToken, ids, amounts);
    }

    function exitTokens(
        address depositor,
        address depositReceiver,
        bytes calldata data
    ) external onlyManager {
        (address rootToken, uint256[] memory ids, uint256[] memory amounts, bytes memory metaData) = 
            abi.decode(data, (address, uint256[], uint256[], bytes));

        bytes memory callData = abi.encodeWithSelector(
            bytes4(0x2eb2c2d6),
            address(this),
            depositReceiver,
            ids,
            amounts,
            metaData
        );

        (bool success, ) = rootToken.call(callData);
        require(success, "exit transfer failed");
    }

    function onERC1155Received(
        address,
        address,
        uint256,
        uint256,
        bytes calldata
    ) external pure returns (bytes4) {
        return ERC1155_RECEIVED;
    }

    function onERC1155BatchReceived(
        address,
        address,
        uint256[] calldata,
        uint256[] calldata,
        bytes calldata
    ) external pure returns (bytes4) {
        return ERC1155_BATCH_RECEIVED;
    }

    function supportsInterface(bytes4 interfaceId) external pure returns (bool) {
        return interfaceId == bytes4(0x01ffc9a7) ||
               interfaceId == bytes4(0x4e2312e0);
    }

    function TOKEN_TYPE() external pure returns (bytes32) {
        return keccak256("ERC1155");
    }

    function DEFAULT_ADMIN_ROLE() external pure returns (bytes32) {
        return bytes32(0);
    }

    function MANAGER_ROLE() external pure returns (bytes32) {
        return keccak256("MANAGER_ROLE");
    }

    function TRANSFER_SINGLE_EVENT_SIG() external pure returns (bytes32) {
