    function uriToTokenId(bytes32 uri) external view returns (uint256) {
        return _uriToTokenId[uri];
    }

    function withdraw(uint256 amount) external {
        require(msg.sender == _owner, "Ownable: caller is not the owner");
        require(amount <= address(this).balance, "Not that much in the contract");
        payable(_owner).transfer(amount);
