        uint256 tokenId = _tokenIdCounter;
        bytes32 uriHash = keccak256(abi.encodePacked(uri));
        require(!_forSale[_uriToTokenId[uriHash]] || _uriToTokenId[uriHash] == 0, "Already sold!!!");
        _tokenIdCounter++;
        _safeMint(msg.sender, tokenId);
